set-variable.value:
@{
		var jwt = (Jwt)context.Variables["jwt"];
		var oid = jwt.Claims.GetValueOrDefault("oid", jwt.Subject ?? "");
		var hash = System.Security.Cryptography.SHA256.Create().ComputeHash(System.Text.Encoding.UTF8.GetBytes("{{user-hash-salt}}" + oid));
		return BitConverter.ToString(hash).Replace("-", "").Substring(0, 32).ToLowerInvariant();
	}
